#
# impact.map -- declarative source-to-target map for ci/prober/verify-impact.
#
# WHY. Every *_test.c links the whole prober LIB (see build.sh:58), so a
# compiler .d file alone would tell you a change to json.c reaches every unit
# binary -- true but useless for selecting the ONE test that actually proves
# the change. This file records the PRIMARY semantic owner explicitly (a
# json.c change is proven first and foremost by json_test) while the LIB-wide
# fallback still applies for anything not listed here (see FALLBACK row).
#
# SCHEMA. TSV, one row per edge, fields separated by a single tab:
#
#   TYPE<TAB>SOURCE<TAB>TARGET<TAB>LANE
#
#   TYPE    one of: PRIMARY, SEMANTIC, FALLBACK, SLOW
#   SOURCE  a path or glob relative to the repo root (ci/prober/json.c,
#           ci/prober/scenarios/backend-smoke/**, ci/prober/fuzz/fuzz_json.c).
#           A bare glob with no directory is matched against the basename.
#   TARGET  the artifact that exercises SOURCE: a unit binary name
#           (json_test), a fuzz target (fuzz/fuzz_json), a scenario dir
#           (scenarios/backend-smoke), a mutation name substring (as passed to
#           mutate.sh's positional filter), or "ALL_UNIT_TESTS" for the LIB
#           fallback.
#   LANE    fast (runs on every PR) or slow (valgrind/weekly/soak -- owner
#           only, verify-impact reports it but does not gate PR CI on it).
#
# Comment lines (#) and blank lines are ignored. Rows are free-form order in
# this file; verify-impact sorts its OWN output, not this map.
#
# GENERATED EDGES. Header (.h) and #include edges are NOT hand-listed here --
# they come from compiler .d files, either emitted by build.sh when
# PROBER_EMIT_DEPS=1 (writes ci/prober/*.d next to each object) or synthesized
# on demand by `verify-impact --regen-deps` (runs $CC -MM per source). Rows
# below marked SEMANTIC are edges no #include expresses (a scenario conf that
# exercises rules.c's reload path, a fuzz target keyed to one parser) and are
# the only hand-written class that is safe to keep by hand: it does not drift
# out of sync with the source the way a header list would.

# --- PRIMARY: one owning unit test per LIB translation unit (build.sh:58) ---
PRIMARY	ci/prober/json.c	json_test	fast
PRIMARY	ci/prober/rules.c	rules_test	fast
PRIMARY	ci/prober/http.c	http_test	fast
PRIMARY	ci/prober/backend.c	backend_test	fast
PRIMARY	ci/prober/util.c	util_test	fast
PRIMARY	ci/prober/assert.c	assert_test	fast

# lib.sh is bash, not a LIB translation unit, but it owns the arithmetic the
# resource oracles assert through and slope_check_test.sh pins that arithmetic
# with no server involved -- so a change to it gets a FAST answer on the PR
# lane here, not only the weekly SLOW scenario rows further down. Those rows
# stay: they cover the live boot/probe path this test deliberately stubs out.
PRIMARY	ci/prober/lib.sh	slope_check_test.sh	fast

# Same reasoning for the two other lib.sh gates that need no server: the stale
# artifact check and the pre-boot conf gate. Both are pure shell over staged
# fixtures, so they answer on the PR lane in milliseconds. check_conf_test.sh
# had no row at all until s143 -- the same unmapped-suite gap that let the
# slope-floor bug (#134) live in a function with zero fast-lane coverage.
PRIMARY	ci/prober/lib.sh	stale_so_test.sh	fast
PRIMARY	ci/prober/lib.sh	check_conf_test.sh	fast

# The suite is its own owner: editing a test must select that test, or the
# selector fails closed on an unmapped executable change (which is exactly what
# it did on the PR that added this file).
PRIMARY	ci/prober/slope_check_test.sh	slope_check_test.sh	fast
PRIMARY	ci/prober/stale_so_test.sh	stale_so_test.sh	fast
PRIMARY	ci/prober/check_conf_test.sh	check_conf_test.sh	fast
PRIMARY	ci/prober/docs_directives_test.sh	docs_directives_test.sh	fast
PRIMARY	ci/prober/schema_emitter_test.sh	schema_emitter_test.sh	fast
PRIMARY	ci/prober/tls_test.sh	tls_test.sh	fast

# The strace summary parser (prober_strace_counts, prober_strace_family_sum)
# lives in lib.sh but is only exercised end-to-end by the syscall-allowlist
# scenario, which cannot produce the shapes that broke it -- an errors row, an
# absent family, a duplicated name. syscall_budget_test.sh feeds those from
# committed fixtures, so a lib.sh edit has to select it or the parser's hostile
# cases go unrun.
PRIMARY	ci/prober/lib.sh	syscall_budget_test.sh	fast
PRIMARY	ci/prober/syscall_budget_test.sh	syscall_budget_test.sh	fast

# test.sh is the RUNNER, not a suite: it discovers *_test.c and *_test.sh and
# aggregates their exit codes. runner_summary_test.sh drives a COPY of it in a
# fixture directory, so it is the suite that actually proves the runner's
# discovery, aggregation and summary reporting.
PRIMARY	ci/prober/test.sh	runner_summary_test.sh	fast
PRIMARY	ci/prober/runner_summary_test.sh	runner_summary_test.sh	fast

# The *_test.c sources own themselves, same rule as the *_test.sh suites above:
# editing a test must select that test, or the selector fails closed on an
# unmapped executable change. These had no rows until the `concurrent` PR, which
# is the first change to touch a unit test's .c file and its LIB source in the
# same diff -- every earlier one edited only the LIB side, so the PRIMARY rows
# above covered it and the gap stayed invisible.
PRIMARY	ci/prober/http_test.c	http_test	fast
PRIMARY	ci/prober/rules_test.c	rules_test	fast

# prober.c is the CLI driver: it links the LIB but no *_test.c links IT
# (build.sh:58 excludes it), so no unit test can own it. The scenario suite is
# what actually executes it -- every scenario boots a server and runs rule files
# through this binary -- so a change here selects the scenarios rather than
# silently mapping to a unit test that never runs the code.
PRIMARY	ci/prober/prober.c	scenarios	slow

# ...and a FAST owner for the CLI wiring specifically. tls_test.sh drives
# prober.c's argv walker and the --tls flag it sets against a plaintext
# responder, with no server boot, so a change to the flag handling answers on
# the PR lane instead of waiting for the weekly scenario run. The slow row
# above stays: it is what covers everything in prober.c that only a live server
# can exercise.
PRIMARY	ci/prober/prober.c	tls_test.sh	fast

# run-scenario.sh is the scenario ENGINE -- it boots the server, renders the
# conf, sources the env file and invokes the prober. Nothing unit-tests it, and
# it had no row at all until the TLS scenario changed it, at which point
# verify-impact correctly failed closed. The scenario tree IS its test: every
# scenario runs through this script, so a change here selects all of them.
PRIMARY	ci/prober/run-scenario.sh	scenarios	slow

# mutate.sh is the mutation gate's own driver. A change to it must re-run the
# gate, or an edit that drops or misanchors a mutant reads as "still 100 caught".
PRIMARY	ci/prober/mutate.sh	mutate	slow

# --- FALLBACK: any LIB .c not caught above (or any LIB .c at all, as the
# conservative catch-all every *_test.c binary links against) still selects
# every unit test, because every *_test.c binary links the whole LIB and a
# defect can surface through any of them regardless of which owns the change
# semantically. This is intentionally coarse -- it is a safety net, not the
# primary selection signal.
FALLBACK	ci/prober/json.c	ALL_UNIT_TESTS	fast
FALLBACK	ci/prober/rules.c	ALL_UNIT_TESTS	fast
FALLBACK	ci/prober/http.c	ALL_UNIT_TESTS	fast
FALLBACK	ci/prober/backend.c	ALL_UNIT_TESTS	fast
FALLBACK	ci/prober/util.c	ALL_UNIT_TESTS	fast
FALLBACK	ci/prober/assert.c	ALL_UNIT_TESTS	fast

# h2.c (H2-2) has no dedicated *_test.c: its whole mechanism is reachable only
# against a real h2-capable `listen ... ssl; http2 on;` server (same reason
# alpn-negotiation's ALPN code in http.c has no unit-test PRIMARY row either),
# so it gets the LIB-wide fallback rather than a PRIMARY pointing at a unit
# binary that does not exist, plus the SEMANTIC row below naming its actual
# owner.
FALLBACK	ci/prober/h2.c	ALL_UNIT_TESTS	fast

# --- SEMANTIC: fuzz targets keyed to the parser they drive (fuzz/fuzz.sh) ---
SEMANTIC	ci/prober/json.c	fuzz/fuzz_json	fast
SEMANTIC	ci/prober/http.c	fuzz/fuzz_http	fast
SEMANTIC	ci/prober/fuzz/fuzz_json.c	fuzz/fuzz_json	fast
SEMANTIC	ci/prober/fuzz/fuzz_http.c	fuzz/fuzz_http	fast
SEMANTIC	ci/prober/fuzz/fuzz_memcached.c	fuzz/fuzz_memcached	fast
SEMANTIC	ci/prober/fuzz/fuzz_resp.c	fuzz/fuzz_resp	fast
SEMANTIC	ci/prober/fuzz/corpus	fuzz/fuzz_json	fast

# --- SEMANTIC: mutation owners (mutate.sh NAME<->file pairing, see mutate.sh)
SEMANTIC	ci/prober/http.c	mutate:send_slow	fast
SEMANTIC	ci/prober/http.c	mutate:abort	fast
SEMANTIC	ci/prober/http.c	mutate:recv_slow	fast
SEMANTIC	ci/prober/http.c	mutate:shutdown	fast
SEMANTIC	ci/prober/http.c	mutate:so_rcvbuf	fast
SEMANTIC	ci/prober/http.c	mutate:hold	fast
SEMANTIC	ci/prober/http.c	mutate:concurrent	fast
SEMANTIC	ci/prober/rules.c	mutate:concurrent	fast
SEMANTIC	ci/prober/rules.c	mutate:shutdown	fast
SEMANTIC	ci/prober/rules.c	mutate:abort	fast
SEMANTIC	ci/prober/rules.c	mutate:send_slow	fast

# --- SEMANTIC: scenario tree exercises the live probe compiled against a
# real nginx/angie -- no #include links ci/prober/scenarios/** back to src/, the
# link is "this scenario's driver.sh boots a probe built from this source".
SEMANTIC	ci/prober/scenarios	scenarios/*	fast

# The TLS scenario's own files. The rule file and conf are covered by the
# scenarios glob above; these two are called out because they are EXECUTABLE
# inputs to the boot path (a gate that exits nonzero, an env file sourced into
# run-scenario.sh's shell), so a change to either alters what the scenario
# actually does rather than only what it asserts.
SEMANTIC	ci/prober/scenarios/tls-listener/requires	scenarios/tls-listener	fast
SEMANTIC	ci/prober/scenarios/tls-listener/env	scenarios/tls-listener	fast
SEMANTIC	src/ngx_test_probe_arm.c	scenarios/*	fast
SEMANTIC	src/ngx_test_probe_arm.c	t/*	fast

# The probe renderer (src/ngx_test_probe.c) emits the document schema_test.c and
# schema_emitter_test.sh pin the SHAPE of, and every scenario boots a server
# built from it. probe-schema.json is the checked-in shape contract those tests
# read. A change to either selects the two schema gates (which run in the
# selftest job, no server) plus the scenario tree (which boots the live probe).
SEMANTIC	src/ngx_test_probe.c	schema_test	fast
SEMANTIC	src/ngx_test_probe.c	scenarios/*	fast
SEMANTIC	probe-schema.json	schema_test	fast

# --- SEMANTIC: the selector's own inputs. impact.map and verify-impact are
# proven by their own self-test, not by any unit/fuzz/scenario target above.
SEMANTIC	ci/prober/impact.map	verify_impact_test.sh	fast
SEMANTIC	ci/prober/verify-impact	verify_impact_test.sh	fast
SEMANTIC	ci/prober/pr-memcheck	pr_memcheck_test	fast

# --- SLOW: owners that only run out-of-band (Valgrind/weekly/soak), not on
# every PR. verify-impact reports these under the "slow" lane so --explain
# can show them, but PR CI (P2-A's own scope) does not gate on the slow lane.
SLOW	ci/prober/backend.c	scenarios/reload-soak	slow
SLOW	ci/prober/http.c	scenarios/soak-delta	slow
SLOW	ci/prober/rules.c	scenarios/property-fuzz	slow
# The resource-scoreboard slope oracle (P2-E) is a soak: it runs N post-warmup
# operations to measure a per-op slope, so it belongs in the weekly/slow lane
# like the other soaks, not the PR path ("PR runs the mapped smallest case;
# slope/soak is weekly" -- plan.md P2-E).
SLOW	ci/prober/lib.sh	scenarios/rss-slope	slow
SLOW	src/ngx_test_probe.c	scenarios/rss-slope	slow
# The stateful property-fuzz model (P2-G5) drives a generated SEQUENCE of
# connection-lifecycle + signal (reload/kill) steps and checkpoints worker
# lineage/log/pool/generation/zone after each. It boots a real server, fires
# signals and drains between steps, so it is a soak on the weekly lane like
# property-fuzz -- not the PR path ("PR runs only models mapped from the diff
# and stays inside P2-C; discovery is weekly" -- plan.md P2-G5). Its lib.sh
# owner is the signal/drain/config-wait helper set it choreographs.
SLOW	ci/prober/rules.c	scenarios/stateful-property-fuzz	slow
SLOW	ci/prober/lib.sh	scenarios/stateful-property-fuzz	slow
SLOW	src/ngx_test_probe.c	scenarios/stateful-property-fuzz	slow
# The named fault matrix (P2-G6) sweeps every fakesrv upstream fault (reset,
# short read, length under/overcount, drip, idle close) through nginx's memcached
# upstream and, after each, reads fd + cycle-pool neutrality from the probe. It
# boots a real server and issues an ordinal-keyed sequence of faulted upstream
# requests, so it is a weekly-lane sweep like property-fuzz -- not the PR path
# ("PR injects only sites in the impact set; weekly sweeps the matrix" -- plan.md
# P2-G6). Its owners are the fake backend's fault model and the probe's resource
# fields the oracle reads.
SLOW	ci/prober/backend.c	scenarios/fault-matrix	slow
SLOW	src/ngx_test_probe.c	scenarios/fault-matrix	slow
# The deployment canary / shadow verifier (P2-H) sequential-boots a CONTROL
# then a CANDIDATE server from the same conf, drives a fixed GET/HEAD request
# plan at each, diffs status/headers/body, and slope-checks the candidate's
# own cycle_used/private_dirty across a post-warmup sweep. Two boots plus a
# slope is a soak like rss-slope -- weekly lane, not the PR path (design pass:
# memory/labs/nginx-module-testkit/design-p2h-canary.md D-8). Its owners are the
# boot/probe/slope helper set (lib.sh) and the probe document the differential
# and O7 growth oracles both read.
SLOW	ci/prober/lib.sh	scenarios/deploy-canary	slow
SLOW	src/ngx_test_probe.c	scenarios/deploy-canary	slow
